import assert from 'node:assert/strict';
import {world,signIn} from './academy-v111-native-fixture.mjs';
export const PLANNING_ORIGIN='https://ummabbadacademy.app';
export const PLANNING_COURSE='COURSE:SEPARATION-A',PLANNING_CLOSED_COURSE='COURSE:SEPARATION-B',PLANNING_RUN='planning-native-run',PLANNING_CLOSED_RUN='planning-native-closed-run',PLANNING_COMPLETE_RUN='planning-native-complete-run';
// Seed actual native tables before accepted setup and split selection. No grants
// are invented: sep-teacher-a already has the genuine Course A TEACHER role.
// Select existing published runs first, then model real live closure in both
// owning fresh stores before V2 capture. The M1 snapshot selector omits runs
// already closed before selection; accepted readers retain live closure narrowing.
function seedPlanningSource(source){const raw=source.db,run=raw.prepare('SELECT * FROM course_runs ORDER BY activity_key,run_id LIMIT 1').get();assert(run);for(const [activityKey,runId,stage]of [[PLANNING_COURSE,PLANNING_RUN,'PUBLISHED'],[PLANNING_COURSE,PLANNING_CLOSED_RUN,'CANCELLED'],[PLANNING_COURSE,PLANNING_COMPLETE_RUN,'COMPLETE'],[PLANNING_CLOSED_COURSE,PLANNING_RUN,'CANCELLED']]){const row={...run,activity_key:activityKey,run_id:runId,name:'Synthetic native planning Course',active:1};const cols=Object.keys(row);raw.prepare('INSERT INTO course_runs('+cols.join(',')+') VALUES('+cols.map(()=>'?').join(',')+')').run(...cols.map(k=>row[k]));raw.prepare("INSERT INTO course_management_drafts(activity_key,run_id,details_json,stage,revision,updated_at,updated_by_account_id) VALUES(?,?,'{}',?,1,'2026-11-19T00:00:00Z','sep-global')").run(activityKey,runId,'PUBLISHED');raw.prepare('INSERT INTO course_run_state(activity_key,run_id,stage) VALUES(?,?,?)').run(activityKey,runId,'PUBLISHED');}}
export async function createPlanningNativeFixture({actor='global',coreDisagreement=false,caseRoleFK=false,hook}={}){let rawAdmin;const f=await world({prepareSource:seedPlanningSource,prepareAcademy:(core,admin)=>{rawAdmin=admin;for(const [key,runId,stage]of [[PLANNING_COURSE,PLANNING_CLOSED_RUN,'CANCELLED'],[PLANNING_COURSE,PLANNING_COMPLETE_RUN,'COMPLETE'],[PLANNING_CLOSED_COURSE,PLANNING_RUN,'CANCELLED']]){core.prepare('UPDATE course_run_state SET stage=? WHERE activity_key=? AND run_id=?').run(stage,key,runId);admin.prepare('UPDATE course_management_drafts SET stage=? WHERE activity_key=? AND run_id=?').run(stage,key,runId);}if(coreDisagreement){core.prepare('INSERT INTO lesson_plan_requirements(activity_key,plans_required) VALUES(?,0)').run(PLANNING_COURSE);}if(caseRoleFK){core.prepare('UPDATE '+(actor==='global'?'global_role_assignments':'role_assignments')+' SET account_id=upper(account_id) WHERE account_id=?').run(actor==='global'?'sep-global':'sep-teacher-a');}},hook});f.envs.academy.ACADEMY_ACCEPTED_SETUP='1';f.loginId=actor==='global'?'separation-global':f.databases.academy.prepare("SELECT login_link_id FROM accounts WHERE account_id='sep-teacher-a'").get().login_link_id;f.login=await signIn(f);f.adminRaw=rawAdmin;f.sub=f.login.context.sub;f.workspace=actor==='global'?'ADMIN':'TEACH';f.call=(action,input)=>f.nativeRequest('/api/academy/planning/'+action,input,f.login,{headers:{'X-Academy-Workspace':f.workspace}});f.resource=(period='WEEKLY',activityKey=PLANNING_COURSE)=>({type:'academy-planning',activityKey,runId:PLANNING_RUN,teacherId:f.sub,period,weekStart:period==='WEEKLY'?'2026-11-16':''});f.key=async resource=>{const b=await f.post('academy','/auth/v2/bootstrap',{purpose:'draft-key',expectedContext:f.login.context});assert.equal(b.response.status,200,b.data.code);return f.post('academy','/auth/v2/draft-key',{resource,operationId:b.data.intent.id,expectedContext:b.data.context,draftGeneration:1,originalExpiresAtMs:b.data.originalExpiresAtMs},b.data);};f.guard=async resource=>{const runtime=f.runtimes.academy,cap=await runtime.authorise(new Request(PLANNING_ORIGIN+'/api/account/session',{headers:{Cookie:f.jar.header(PLANNING_ORIGIN)}}));return (await import('../../../security/v2/academy-planning-resources.mjs')).academyPlanningDraftGuard({runtime,store:runtime.store,env:f.envs.academy,cap,binding:cap.binding,rights:cap.rights,resource});};f.renew=async()=>{const b=await f.post('academy','/auth/v2/bootstrap',{purpose:'refresh',expectedContext:f.login.context}),r=await f.post('academy','/auth/v2/refresh',{operationId:b.data.intent.id,expectedContext:b.data.context,qualifyingActivity:false},b.data);assert.equal(r.response.status,200,r.data.code);f.login=r.data;};f.cleanup=async()=>{await f.drainNativeBackground();f.close();};return f;}
